114	// curatedSkill represents a known review skill/command surfaced by the
115	// first-run picker. Users can add custom skills by editing
116	// .entire/settings.json directly.
117	type curatedSkill struct {
118		Name string
119		Desc string
120	}
121	
122	// curatedReviewSkills groups known review skills by agent name (as a string
123	// matching types.AgentName values). Agents not listed here still work via
124	// the picker — users just see an empty list and should edit settings.json
125	// manually to add skills.
126	var curatedReviewSkills = map[string][]curatedSkill{
127		"claude-code": {
128			{Name: "/pr-review-toolkit:review-pr", Desc: "Full PR review"},
129			{Name: "/pr-review-toolkit:code-reviewer", Desc: "Code review for standards"},
130			{Name: "/test-auditor", Desc: "Test coverage audit"},
131			{Name: "/verification-before-completion", Desc: "Verify before marking done"},
132			{Name: "/requesting-code-review", Desc: "Prepare code for review"},
133			{Name: "/pr-review-toolkit:silent-failure-hunter", Desc: "Find suppressed errors"},
134		},
135		"codex": {
136			{Name: "/codex:review", Desc: "Codex review"},
137			{Name: "/codex:adversarial-review", Desc: "Adversarial review — red-team"},
138		},
139	}
