190	// runReviewConfigPicker presents a huh multi-select for each installed agent
191	// that has curated review skills, and saves the selection to
192	// .entire/settings.json. Previously-saved skills are pre-checked via
193	// huh.Option.Selected(true), mirroring how `entire enable` preserves prior
194	// selections in its own agent picker.
195	func runReviewConfigPicker(ctx context.Context, out io.Writer) (map[string][]string, error) {
196		installed := GetAgentsWithHooksInstalled(ctx)
197		if len(installed) == 0 {
198			return nil, errors.New("no agents installed; run 'entire enable' first")
199		}
200	
201		// Narrow to agents that have a curated skills list; others need manual
202		// editing of settings.json under review.<agent-name>.
203		type configurableAgent struct {
204			name types.AgentName
205			ag   agent.Agent
206		}
207		var configurable []configurableAgent
208		for _, name := range installed {
209			curated, ok := curatedReviewSkills[string(name)]
210			if !ok || len(curated) == 0 {
211				continue
212			}
213			ag, err := agent.Get(name)
214			if err != nil {
215				continue
216			}
217			configurable = append(configurable, configurableAgent{name: name, ag: ag})
218		}
219		if len(configurable) == 0 {
220			return nil, errors.New(
221				"no installed agents have curated review skills; " +
222					"edit .entire/settings.json directly under review.<agent-name>",
223			)
224		}
225	
226		// Load existing config so we can pre-check saved skills. A load error
227		// here means the settings file is malformed; log at Warn so users
228		// debugging "my saved skills aren't pre-checked" can see why, but keep
229		// going with an empty prefill — runReview already surfaces the same
230		// error distinctly when it's the first load.
231		existing := map[string][]string{}
232		if s, err := settings.Load(ctx); err != nil {
233			logging.Warn(ctx, "settings.Load failed when pre-filling picker", slog.String("error", err.Error()))
234		} else if s != nil {
235			existing = s.Review
236		}
237	
238		// Up-front header: make the order and count obvious so users can spot
239		// when an agent they expected isn't being offered (e.g., hooks not
240		// installed for it yet).
241		labels := make([]string, 0, len(configurable))
242		for _, c := range configurable {
243			labels = append(labels, string(c.ag.Type()))
244		}
245		fmt.Fprintf(out, "Configuring review skills for %d agent(s): %s\n", len(configurable), strings.Join(labels, ", "))
246		fmt.Fprintln(out, "(Previously-saved skills are pre-checked. Space to toggle, enter to confirm.)")
247		fmt.Fprintln(out)
248	
249		selected := map[string][]string{}
250		for i, c := range configurable {
251			curated := curatedReviewSkills[string(c.name)]
252			savedSet := map[string]struct{}{}
253			for _, s := range existing[string(c.name)] {
254				savedSet[s] = struct{}{}
255			}
256	
257			options := make([]huh.Option[string], 0, len(curated))
258			for _, s := range curated {
259				opt := huh.NewOption(fmt.Sprintf("%s — %s", s.Name, s.Desc), s.Name)
260				if _, ok := savedSet[s.Name]; ok {
261					opt = opt.Selected(true)
262				}
263				options = append(options, opt)
264			}
265	
266			// huh populates picks from Option.Selected(true) — do NOT pre-seed,
267			// matching the convention used in detectOrSelectAgent (setup.go).
268			var picks []string
269			title := fmt.Sprintf("[%d/%d] Review skills for %s", i+1, len(configurable), c.ag.Type())
270			form := NewAccessibleForm(huh.NewGroup(
271				huh.NewMultiSelect[string]().
272					Title(title).
273					Description(fmt.Sprintf("Agent: %s", c.ag.Type())).
274					Options(options...).
275					Value(&picks),
276			))
277			if err := form.Run(); err != nil {
278				return nil, fmt.Errorf("picker for %s: %w", c.name, err)
279			}
280			if len(picks) > 0 {
281				selected[string(c.name)] = picks
282			}
283		}
284		if len(selected) == 0 {
285			return nil, errors.New("no review skills selected")
286		}
287		if err := saveReviewConfig(ctx, selected); err != nil {
288			return nil, err
289		}
290		fmt.Fprintln(out, "Saved review config to .entire/settings.json. Edit directly or run `entire review --edit`.")
291		return selected, nil
292	}
