588	// formatReviewScope renders a one-line summary for the user. Empty-review
589	// cases fall back to "no changes detected".
590	func formatReviewScope(s reviewScope) string {
591		head := s.Branch
592		if head == "" {
593			head = detachedHEADDisplay + " " + s.HeadSHA
594		}
595		var parts []string
596		if s.Base != "" && s.Branch != "" && s.Base != s.Branch && (s.AheadCommits > 0 || s.FilesChanged > 0) {
597			parts = append(parts,
598				fmt.Sprintf("%d commits", s.AheadCommits),
599				fmt.Sprintf("%d files changed", s.FilesChanged),
600			)
601		}
602		if s.Uncommitted > 0 {
603			parts = append(parts, fmt.Sprintf("%d uncommitted", s.Uncommitted))
604		}
605		suffix := "no changes detected"
606		if len(parts) > 0 {
607			suffix = strings.Join(parts, ", ")
608		}
609		if s.Base != "" && s.Branch != "" && s.Base != s.Branch {
610			return fmt.Sprintf("Reviewing %s vs %s: %s", head, s.Base, suffix)
611		}
612		return fmt.Sprintf("Reviewing %s: %s", head, suffix)
613	}
